import {readFileSync,writeFileSync,mkdirSync} from 'node:fs';
import {join,dirname,resolve} from 'node:path';
import {createCoverageMap} from 'istanbul-lib-coverage';
import {instrumentTypeScriptWithCoverage} from '../scripts/run-istanbul-bun-coverage';
import {createOwnedTestDirectory} from '../tests/helpers/owned-test-directory';
import {sourceHash} from '../scripts/quality-inventory';
const root=process.cwd(),storage=createOwnedTestDirectory('memory-core-diagnostic-');
const repositories=["src/infrastructure/database/repositories/message-repository.ts","src/infrastructure/database/repositories/entity-repository.ts","src/infrastructure/database/repositories/session-repository.ts"];
const driver="tests/infrastructure/database/repositories/core-lifecycle.test.ts",paths=[...repositories,driver];
const tests=["tests/infrastructure/database/repositories/core-lifecycle.test.ts","src/infrastructure/database/repositories/message-repository.test.ts","src/infrastructure/database/repositories/entity-repository.test.ts","src/infrastructure/database/repositories/session-repository.test.ts"];
const mode=process.argv[2]??'measure';if(!['measure','faults'].includes(mode))throw Error('Invalid mode');
const originals=new Map(paths.map(path=>[path,readFileSync(path,'utf8')]));
function put(path:string,content:string){mkdirSync(dirname(join(storage.dir,path)),{recursive:true});writeFileSync(join(storage.dir,path),content);}
const runs:any[]=[];
try{
 for(const path of tests.slice(1))put(path,readFileSync(path,'utf8'));
 for(const path of ['src/infrastructure/database/connection.ts','src/infrastructure/database/owned-database.ts','src/infrastructure/database/schema.ts','src/domain/entities/message.ts','src/domain/entities/entity.ts','src/domain/entities/session.ts','src/domain/value-objects/project-path.ts','src/domain/errors/unknown-error.ts','src/application/services/fts-sanitizer.ts','src/infrastructure/hooks/hook-runner.ts','src/application/services/llm-extractor.ts'])put(path,'export * from '+JSON.stringify(join(root,path).replaceAll('\\','/'))+';');
 put('capture.ts','import {afterAll} from "bun:test";import {writeFileSync} from "node:fs";afterAll(()=>writeFileSync("coverage.json",JSON.stringify((globalThis as any).__coverage__)));');
 put('bunfig.toml','[test]\ncoverage=false\npreload=['+JSON.stringify(join(root,'tests/test-setup.ts').replaceAll('\\','/'))+(mode==='measure'?',"./capture.ts"':'')+']\n');
 const faults:any[]=mode==='faults'?[
  ...repositories.flatMap(path=>[...originals.get(path)!.matchAll(/using \w+ =/g)].map((match,index)=>({path,index,offset:match.index,from:'using',to:'const',kind:'missing-disposal'}))),
  ...repositories.map(path=>({path,offset:originals.get(path)!.indexOf('this.db.transaction('),from:'this.db.transaction(',to:'((callback: any) => ({ immediate: callback }))(',kind:'missing-transaction'})),
  {path:repositories[0],offset:originals.get(repositories[0]!)!.indexOf('if (!this.db.inTransaction) throw err;'),from:'if (!this.db.inTransaction) throw err;',to:'',kind:'continue-after-rollback'},
  {path:repositories[0],offset:originals.get(repositories[0]!)!.indexOf('if (existsStatement.get(message.id))'),from:'if (existsStatement.get(message.id))',to:'if (true)',kind:'false-insert-count'},
  ...[...originals.get(repositories[1]!)!.matchAll(/if \((?:inserted|updated)\.changes === 0\) throw new Error\([^;]+;/g)].map(match=>({path:repositories[1],offset:match.index,from:match[0],to:'',kind:'ignored-entity-write'})),
  ...[...originals.get(repositories[1]!)!.matchAll(/Number\(inserted\.lastInsertRowid\)/g)].map(match=>({path:repositories[1],offset:match.index,from:match[0],to:match[0]+' + 1',kind:'wrong-insert-id'})),
  {path:repositories[1],offset:0,from:'',to:'',kind:'interpolated-limit'},
  ...[...originals.get(repositories[2]!)!.matchAll(/\)\.length;/g)].map(match=>({path:repositories[2],offset:match.index,from:match[0],to:').length + 1;',kind:'wrong-write-count'})),
 ]:[];
 for(const fault of [null,...faults]){
  for(const [path,content]of originals)put(path,mode==='measure'?instrumentTypeScriptWithCoverage(content,resolve(path)).code:content);
  if(fault){const content=originals.get(fault.path)!;if(fault.offset<0)throw Error('Missing fault target');
   const changed=fault.kind==='interpolated-limit'?content.replace('"LIMIT $limit"',String.fromCharCode(96)+'LIMIT '+String.fromCharCode(36)+'{options.limit}'+String.fromCharCode(96)).replace('if (options?.limit) params.$limit = options.limit;',''):content.slice(0,fault.offset)+fault.to+content.slice(fault.offset+fault.from.length);
   if(changed===content)throw Error('No-op fault');put(fault.path,changed);}

  const command=[process.execPath,'test','--timeout','15000',...(mode==='measure'?tests:[driver])];
  const child=Bun.spawnSync(command,{cwd:storage.dir,env:{...process.env,TEMP:storage.dir,TMP:storage.dir,TMPDIR:storage.dir},stdout:'pipe',stderr:'pipe',timeout:45000});
  const output=new TextDecoder().decode(child.stdout)+new TextDecoder().decode(child.stderr);
  runs.push({fault,command,exit:child.exitCode,output});
  if(fault?child.exitCode===0||!output.includes('(fail)'):child.exitCode!==0)throw Error('Unexpected result\n'+output);
 }
 let measurement:unknown;
 if(mode==='measure'){
  const raw=JSON.parse(readFileSync(join(storage.dir,'coverage.json'),'utf8')),map=createCoverageMap(raw);
  const files=paths.map(path=>{const measured=map.fileCoverageFor(resolve(path)),data=measured.data;return{path,sourceHash:sourceHash(originals.get(path)!),metrics:measured.toSummary().data,uncoveredBranches:Object.entries(data.b).flatMap(([id,hits])=>hits.flatMap((count,index)=>count===0?[{id,index,location:data.branchMap[id]?.locations[index]}]:[])),uncoveredFunctions:Object.entries(data.f).filter(([,hits])=>hits===0).map(([id])=>data.fnMap[id])};});
  measurement={files,rawCoverage:raw};console.log(JSON.stringify(files));
 }else console.log(JSON.stringify(runs.map(run=>({fault:run.fault,exit:run.exit}))));
 writeFileSync(`.git/b11-core-${mode}.json`,JSON.stringify({recordedAt:new Date().toISOString(),scope:'Scoped diagnostic; full instrumenter/platform/package/changed-line and independent review acceptance remains open.',runtime:Bun.version,sourceInputs:paths.map(path=>({path,sourceHash:sourceHash(originals.get(path)!)})),runs,measurement,source:readFileSync('.git/b11-core-diagnostic.ts','utf8')},null,2)+'\n');
}finally{storage.cleanup();}

