import {strict as assert} from 'node:assert';
import {readFileSync,writeFileSync,existsSync} from 'node:fs';
import {resolve} from 'node:path';
import {createCoverageMap} from 'istanbul-lib-coverage';
import {discoverInventory,validateInventory,sourceHash} from '../scripts/quality-inventory';
const base='.planning/memory-resilience/',read=(p:string)=>JSON.parse(readFileSync(p,'utf8'));
const path=base+'evidence/B11.74.3-core.json',record=read(path),catalog=discoverInventory(process.cwd());
assert.equal(catalog.files.length,457);assert.equal(catalog.packages.length,2);assert.deepEqual(catalog,read(base+'executable-catalog.json'));assert.deepEqual(validateInventory(catalog,read(base+'quality-classifications.json')),[]);
for(const input of [...record.sourceInputs,...record.otherInputs])assert.equal(input.sourceHash,sourceHash(readFileSync(input.path,'utf8')));
for(const input of record.sourceInputs)for(const rows of [record.diagnosticCoverage.sourceInputs,record.decisionChecks.sourceInputs,record.native.sourceInputs])assert.equal(rows.find((r:any)=>r.path===input.path).sourceHash,input.sourceHash);
const coverage=createCoverageMap(record.diagnosticCoverage.measurement.rawCoverage);
for(const entry of record.diagnosticCoverage.measurement.files){assert.deepEqual(coverage.fileCoverageFor(resolve(entry.path)).toSummary().data,entry.metrics);for(const metric of Object.values(entry.metrics)as any[])assert.equal(metric.pct,100);}
for(const run of [record.checks[0],...record.native.runs]){assert.equal(run.exit,0);assert(run.output.includes('130 pass')&&run.output.includes('0 fail')&&run.output.includes('1639 expect()'));}
assert.equal(record.decisionChecks.runs.length,46);assert.equal(record.decisionChecks.runs[0].exit,0);for(const run of record.decisionChecks.runs.slice(1)){assert.equal(run.exit,1);assert(run.output.includes('(fail)'));}
assert(!existsSync(record.removedRuntimeRoot));
const ledger=read(base+'work-items.json'),items=new Map<string,any>(ledger.items.map((i:any)=>[i.id,i])),done=new Set<string>();
function visit(id:string,stack=new Set<string>()){assert(items.has(id)&&!stack.has(id),'Invalid dependency '+id);if(done.has(id))return;for(const dep of items.get(id).depends_on)visit(dep,new Set([...stack,id]));done.add(id);}
assert.equal(items.size,232);assert.equal(items.size,ledger.items.length);for(const id of items.keys())visit(id);
assert.equal(ledger.current_item,'B11.74.4');assert.equal(items.get('B11.74.3').status,'verified');assert.deepEqual(ledger.items.filter((i:any)=>i.status==='active').map((i:any)=>i.id),['B11.74.4']);
const inventory=items.get('B11.74.3').progress.repositoryInventory;assert.equal(inventory.length,17);assert.equal(inventory.filter((r:any)=>r.status.startsWith('local')).length,17);assert.equal(inventory.filter((r:any)=>r.status.startsWith('local')).reduce((n:number,r:any)=>n+r.nativePrepareSites,0),128);
for(const entry of inventory)assert.equal(entry.sourceHash,sourceHash(readFileSync(entry.path,'utf8')));
for(const [index,input]of record.sourceInputs.slice(0,3).entries()){const source=readFileSync(input.path,'utf8');assert.equal([...source.matchAll(/this\.db\.prepare[<(]/g)].length,[4,9,13][index]);assert.equal([...source.matchAll(/using \w+ =/g)].length,[5,12,14][index]);assert(!source.includes('this.db.query('));assert(!/private readonly \w+Stmt/.test(source));}
for(const input of record.constructorCallers.paths)assert.equal(input.sourceHash,sourceHash(readFileSync(input.path,'utf8')));
for(const id of ['Q022','Q028']){assert.equal(items.get(id).status,'pending');assert.deepEqual(items.get(id).depends_on,['B11.74.3']);assert(items.get('B11.74.7').depends_on.includes(id));}
assert(items.get('B11.74.7').progress.coreAcceptance);assert(items.get('B11.74.5').progress.sessionSummaryIndexReview);
const acceptancePath=base+'evidence/B11.74.3.json',acceptance=read(acceptancePath);assert.equal(acceptance.bindings.length,17);
for(const binding of acceptance.bindings){assert.equal(binding.sourceHash,sourceHash(readFileSync(binding.path,'utf8')));assert.equal(binding.evidenceHash,sourceHash(readFileSync(binding.evidence,'utf8')));const proof=read(binding.evidence);assert(proof.sourceInputs.some((input:any)=>input.path===binding.path&&input.sourceHash===binding.sourceHash));}
assert.equal(acceptance.audit.totalPrepares,127);assert.equal(acceptance.audit.currentQuerySites,0);assert.equal(acceptance.audit.currentRetainedFields,0);assert.equal(acceptance.negativeAudit.runs.length,3);for(const run of acceptance.negativeAudit.runs)assert.equal(run.exit,1);
assert.equal(items.get('B11.74').status,'pending');assert.equal(items.get('B11.74.6').status,'pending');assert(!readFileSync('src/infrastructure/database/connection.ts','utf8').includes('OwnedDatabase'));
record.validation={command:'bun .git/b11-core-validate.ts',exit:0,recordedAt:new Date().toISOString(),result:'457-file/two-package inventory and 232-item acyclic ledger reconcile. All seventeen repositories reconcile to127current/128original prepares, zero retained fields/queries. B11.74.3 native lifetime scope verified; B11.74.4 active. Final source/native/metric/fault evidence agrees; full acceptance and factory activation pending.',source:readFileSync('.git/b11-core-validate.ts','utf8')};
writeFileSync(path,JSON.stringify(record,null,2)+'\n');acceptance.bindings.find((row:any)=>row.evidence===path).evidenceHash=sourceHash(readFileSync(path,'utf8'));acceptance.validation=record.validation;writeFileSync(acceptancePath,JSON.stringify(acceptance,null,2)+'\n');console.log(record.validation.result);
